function renderPress(){document.getElementById('pressFacts').innerHTML=D.pressFacts.map((f,i)=>`<div class="fact"><div class="factMeta">${epBadge('fact')}</div><div class="num">${typeof f.num==='number'?fmtNum(f.num):esc(f.num)}</div><p>${t(f.key)}</p><div class="factActions"><a class="linkBtn" href="${f.source}" target="_blank" rel="noopener">${t('source')} ↗</a><button class="miniBtn" data-copy="${f.key}">${t('copyFact')}</button></div></div>`).join('');document.querySelectorAll('[data-copy]').forEach(b=>b.onclick=async()=>{const f=D.pressFacts.find(x=>x.key===b.dataset.copy),tx=t(b.dataset.copy)+(f?.source?`\nSource: ${f.source}`:'');try{await navigator.clipboard.writeText(tx);const old=b.textContent;b.textContent=t('copied');setTimeout(()=>b.textContent=old,900)}catch(e){}});const guideCard=(n,kind)=>`<div class="precisionCard"><div class="precisionSide"><div class="precisionMeta">${epBadge(kind)}</div><span class="precisionLabel">${t('sayThis')}</span><p>${t('safe'+n)}</p></div><div class="precisionDivider"></div><div class="precisionSide mutedSide"><span class="precisionLabel">${t('notThis')}</span><p>${t('avoid'+n)}</p></div></div>`;document.getElementById('guideRows').innerHTML=[2,3].map(n=>guideCard(n,'fact')).join('');const lgr=document.getElementById('luganoGuideRows');if(lgr)lgr.innerHTML=[1,4].map(n=>guideCard(n,n===1?'fact':'vision')).join('');document.getElementById('angleGrid').innerHTML=[1,2,3,4,5].map(n=>`<div class="angle">${t('angle'+n)}</div>`).join('')}
