function mapXY(lon,lat){return{x:(lon+180)/360*1000,y:(90-Math.max(-60,Math.min(85,lat)))/180*500}}
let geoMode=['governance','rsp','applicant2012','applicant2026'].includes(qp.get('map'))?qp.get('map'):'governance';
function renderGeoMap(){
 const el=document.getElementById('geoMap'); if(!el)return; const path=window.DOT_WORLD_PATH||'';
 let layer='';
 if(geoMode==='governance'){
  layer=D.governanceNodes.map(d=>{const p=mapXY(d.lon,d.lat);return `<g class="mapDatum" data-tip="${d.name} — ${t(d.detailKey)}" tabindex="0" role="button" aria-label="${esc(t('mapItemLabel').replace('{name}',d.name))}"><circle class="mapPoint ${d.kind}" cx="${p.x}" cy="${p.y}" r="${d.kind==='core'?7:5}"></circle><text class="mapLabel" x="${p.x+8}" y="${p.y-8}">${d.name.replace('ICANN ','')}</text></g>`}).join('');
 }else if(geoMode==='rsp'){
  layer=D.rspRegions.map(d=>{const p=mapXY(d.lon,d.lat),r=d.count?16+Math.sqrt(d.count)*7:14;return `<g class="mapDatum" tabindex="0" role="button" aria-label="${esc(t('mapItemLabel').replace('{name}',d.name))}" data-tip="${d.name}: ${d.count} ${t('rspEvaluated')}"><circle class="mapBubble ${d.count?'':'zero'}" cx="${p.x}" cy="${p.y}" r="${r}"></circle><text class="mapBubbleLabel" x="${p.x}" y="${p.y+4}">${d.count}</text><text class="mapLabel" x="${p.x}" y="${p.y+r+16}" text-anchor="middle">${d.code}</text></g>`}).join('');
 }else if(geoMode==='applicant2012'){
  layer=D.geoApplicantRegions2012.map(d=>{const p=mapXY(d.lon,d.lat),r=16+Math.sqrt(d.count)*1.2;return `<g class="mapDatum" tabindex="0" role="button" aria-label="${esc(t('mapItemLabel').replace('{name}',d.name))}" data-tip="${d.name}: ${d.count} ${t('applications')}"><circle class="mapBubble applicantBubble" cx="${p.x}" cy="${p.y}" r="${r}"></circle><text class="mapBubbleLabel" x="${p.x}" y="${p.y+4}">${d.count}</text><text class="mapLabel" x="${p.x}" y="${p.y+r+16}" text-anchor="middle">${d.code}</text></g>`}).join('');
 }else{
  const ready=(D.geoApplicantRegions2026||[]).some(d=>d.count!==null&&d.count!==undefined);
  layer=ready?D.geoApplicantRegions2026.map(d=>{const p=mapXY(d.lon,d.lat),r=16+Math.sqrt(d.count||0)*1.2;return `<g class="mapDatum" tabindex="0" role="button" aria-label="${esc(t('mapItemLabel').replace('{name}',d.name))}" data-tip="${d.name}: ${d.count} ${t('applications')}"><circle class="mapBubble applicantBubble" cx="${p.x}" cy="${p.y}" r="${r}"></circle><text class="mapBubbleLabel" x="${p.x}" y="${p.y+4}">${d.count}</text><text class="mapLabel" x="${p.x}" y="${p.y+r+16}" text-anchor="middle">${d.code}</text></g>`}).join(''):`<g class="mapPending"><text x="500" y="235" text-anchor="middle" class="mapPendingTitle">${t('awaitRevealShort')}</text><text x="500" y="263" text-anchor="middle" class="mapPendingSub">${t('applicantRegion2026')}</text></g>`;
 }
 el.innerHTML=`<svg viewBox="0 0 1000 500" role="img" aria-label="${t('geoTitle')}"><path class="worldCountry" d="${path}"></path>${layer}</svg>`;
 const note=document.getElementById('geoNote'); if(note)note.innerHTML=t(geoMode==='governance'?'geoGovernanceNote':geoMode==='rsp'?'geoRspNote':geoMode==='applicant2012'?'applicantRegion2012Note':'applicantRegion2026Note');
 let tt=document.getElementById('mapTooltip'); if(!tt){tt=document.createElement('div');tt.id='mapTooltip';tt.className='mapTooltip';document.body.appendChild(tt)}
 el.querySelectorAll('.mapDatum').forEach(g=>{g.addEventListener('pointerenter',e=>{tt.textContent=g.dataset.tip;tt.style.display='block'});g.addEventListener('pointermove',e=>{tt.style.left=(e.clientX+14)+'px';tt.style.top=(e.clientY+14)+'px'});g.addEventListener('pointerleave',()=>tt.style.display='none');g.addEventListener('focus',()=>{tt.textContent=g.dataset.tip;tt.style.display='block';const r=g.getBoundingClientRect();tt.style.left=(r.left+12)+'px';tt.style.top=(r.bottom+8)+'px'});g.addEventListener('blur',()=>tt.style.display='none');g.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();tt.textContent=g.dataset.tip;tt.style.display='block'}});g.addEventListener('click',e=>{tt.textContent=g.dataset.tip;tt.style.display='block';tt.style.left=(e.clientX+14)+'px';tt.style.top=(e.clientY+14)+'px'})});
 document.querySelectorAll('.mapToggle').forEach(b=>b.classList.toggle('active',b.dataset.mapmode===geoMode));setQuery();
}
